        private void MyCanvas_KeyDown(object sender, KeyEventArgs e)
        {
            if (e.Key == Key.Left)
                dungeon.MoveMap(new Point (dungeon.cur_pos.X - 1, dungeon.cur_pos.Y));
            else if (e.Key == Key.Right)
                dungeon.MoveMap(new Point(dungeon.cur_pos.X + 1, dungeon.cur_pos.Y));
            dungeon.Render(MyCanvas);
        }
    }
